export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const key='try-study-v1';
export const fresh=()=>({version:1,read:{},resume:{},notes:{},bookmarks:[],attempts:[],drafts:{},mistakes:{},activity:{},goal:20,lastCourse:'ch01'});
let initial;try{initial={...fresh(),...JSON.parse(localStorage.getItem(key)||'null')};}catch{initial=fresh();}
export const state=initial;
export function day(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function activity(){return state.activity[day()]??=( {seconds:0,slides:0,quizzes:0});}
export function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('พื้นที่จัดเก็บไม่พอ กรุณาส่งออกข้อมูลสำรอง');}}
export let courses=[];
export function setCourses(v){courses.splice(0,courses.length,...v);}
export const course=id=>courses.find(c=>c.id===id);
export const readCount=c=>(state.read[c.id]||[]).filter(p=>p>=1&&p<=c.pages.length).length;
export const pct=c=>Math.round(readCount(c)/c.pages.length*100);
export const levelLabel={easy:'ง่าย',medium:'ปานกลาง',hard:'ยาก'};
export const lastScore=c=>state.attempts.filter(a=>a.courseId===c.id&&a.mode!=='practice').at(-1);
export const topicAt=(c,p)=>c.topics?.find(t=>p>=t.from&&p<=t.to);
export function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),3200);}
export function go(hash){if(location.hash===hash)window.dispatchEvent(new HashChangeEvent('hashchange'));else location.hash=hash;}
export function empty(title,desc,action=''){return `<div class="empty">${icon('book')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;}
export const btn=(text,attrs='',kind='')=>`<button class="button ${kind}" ${attrs}>${text}</button>`;
export function modal(html){document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;document.querySelector('.modal button,.modal input')?.focus();}
export function closeModal(){document.getElementById('modal-root').innerHTML='';}
let dbPromise;
export function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('try-study-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('courses',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function storedCourses(){const d=await db();return new Promise((res,rej)=>{const r=d.transaction('courses').objectStore('courses').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
export async function putCourse(c){const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('courses','readwrite');tx.objectStore('courses').put(c);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error);});}
export async function deleteCourse(id){const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('courses','readwrite');tx.objectStore('courses').delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});}
export function card(c){const percent=pct(c),status=percent===100?'done':percent?'started':'';return `<article class="course-card"><a href="#learn/${c.id}/${state.resume[c.id]||1}" aria-label="เรียน ${esc(c.title)}"><div class="course-cover ${c.color}"><span class="chapter-label">${c.custom?'YOUR REFERENCE':c.n===0?'BEFORE YOU BEGIN':'CHAPTER '+String(c.n).padStart(2,'0')}</span><span class="pdf-label">บทสอน</span>${icon(c.icon)}</div></a><div class="course-body"><h3><a href="#learn/${c.id}/${state.resume[c.id]||1}">${esc(c.title)}</a></h3><p class="thai">${esc(c.thai)}</p><div class="course-meta"><span>${icon('file')}${c.pages.length} หน้า</span><span>${icon('quiz')}${c.questions.length?c.questions.length+' ข้อ':c.n===0?'บทนำ':'เอกสารอ้างอิง'}</span></div><div class="progress-track"><span style="width:${percent}%"></span></div><div class="course-progress"><span>ความก้าวหน้า</span><b>${percent}%</b></div><div class="course-footer"><span class="status ${status}">${percent===100?'เรียนครบแล้ว':percent?'กำลังเรียน':'ยังไม่เริ่ม'}</span>${c.custom?'':`<a class="course-summary-link" href="#summary/${c.id}">สรุปเนื้อหา</a>`}<a href="#learn/${c.id}/${state.resume[c.id]||1}">${percent?'เรียนต่อ':'เริ่มเรียน'} ${icon('arrow')}</a></div></div></article>`;}
export function heading(title,desc,right=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${right}</div>`;}
export const progressBar=n=>`<div class="progress-track"><span style="width:${Math.max(0,Math.min(100,n))}%"></span></div>`;
